create table if not exists service_goods_policies(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),shipping_service_id uuid not null references shipping_services(id) on delete cascade,goods_category text not null,decision text not null check(decision in ('ALLOWED','REVIEW_REQUIRED','RESTRICTED','PROHIBITED')),required_documents jsonb not null default '[]',handling_instructions text,active boolean not null default true,unique(shipping_service_id,goods_category));
create table if not exists service_price_adjustments(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),shipping_service_id uuid not null references shipping_services(id) on delete cascade,adjustment_code text not null,adjustment_name text not null,adjustment_type text not null check(adjustment_type in ('FIXED','PERCENTAGE')),amount_minor bigint,percentage numeric(7,4),client_id uuid references clients(id),goods_category text,min_weight_kg numeric(18,3),effective_from timestamptz not null default now(),effective_until timestamptz,active boolean not null default true,priority integer not null default 100,created_at timestamptz not null default now());
create table if not exists pricing_simulation_snapshots(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),shipping_service_id uuid not null references shipping_services(id),client_id uuid references clients(id),input_payload jsonb not null,result_payload jsonb not null,pricing_version_fingerprint text not null,created_by text,created_at timestamptz not null default now());
create index if not exists idx_service_goods_policy on service_goods_policies(org_id,shipping_service_id,goods_category);
create index if not exists idx_service_adjustments_effective on service_price_adjustments(org_id,shipping_service_id,effective_from,effective_until);
create index if not exists idx_pricing_snapshots_tenant on pricing_simulation_snapshots(org_id,created_at desc);
